             <label><input type="checkbox" name="q3" value="HTML">HTML</label>
           </div>
         </fieldset>
       </div>

       <button type="submit">Submit Quiz</button>
       <output id="result" class="result" aria-live="polite"></output>
     </form>
   </main>

   <script>
     const answers = {
       q1: ["JavaScript", "HTML", "CSS"],
       q2: ["Java", "C#", "Go"],
       q3: ["Python", "R", "SQL"]
     };

     const form = document.getElementById("quiz-form");
     const result = document.getElementById("result");

     function getSelections(name) {
       return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);
     }

     function matchesAnswer(selected, correct) {
       return selected.length === correct.length && selected.every((choice) => correct.includes(choice));
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       let score = 0;

       Object.entries(answers).forEach(([question, correct]) => {
         const selected = getSelections(question);
         if (matchesAnswer(selected, correct)) {
           score += 1;
         }
       });

       result.textContent = `You scored ${score} out of ${Object.keys(answers).length}.`;
     });
   </script>
 </body>
 </html>

